{
    "sql": "WITH FemaleClients AS (SELECT c.client_id, c.birth_date, d.account_id, d.type FROM client c JOIN disp d ON c.client_id = d.client_id WHERE c.gender = 'F' AND d.type = 'OWNER'), OldestFemaleClients AS (SELECT account_id FROM FemaleClients WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClients)), SalaryStats AS (SELECT t.account_id, AVG(t.amount) AS avg_salary FROM trans t JOIN OldestFemaleClients o ON t.account_id = o.account_id WHERE t.operation = 'CREDIT' GROUP BY t.account_id), MinMaxSalary AS (SELECT MIN(avg_salary) AS lowest_avg_salary, MAX(avg_salary) AS highest_avg_salary FROM SalaryStats) SELECT s.account_id, (m.highest_avg_salary - m.lowest_avg_salary) AS salary_gap FROM SalaryStats s, MinMaxSalary m WHERE s.avg_salary = m.lowest_avg_salary"
}

{
    "sql": "WITH FemaleAccounts AS (SELECT a.account_id, c.client_id, c.birth_date, d.A11 AS avg_salary FROM account a JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F'), OldestFemale AS (SELECT account_id, avg_salary FROM FemaleAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleAccounts)), LowestAvgSalary AS (SELECT account_id, avg_salary FROM OldestFemale WHERE avg_salary = (SELECT MIN(avg_salary) FROM OldestFemale)), HighestAvgSalary AS (SELECT MAX(avg_salary) AS max_salary FROM FemaleAccounts) SELECT l.account_id, l.avg_salary AS lowest_avg_salary, h.max_salary AS highest_avg_salary, (h.max_salary - l.avg_salary) AS salary_gap FROM LowestAvgSalary l CROSS JOIN HighestAvgSalary h"
}

{
    "sql": "WITH FemaleClientAccounts AS (SELECT a.account_id, c.client_id, c.birth_date, d.A11 AS avg_salary FROM account a JOIN disp dp ON a.account_id = dp.account_id JOIN client c ON dp.client_id = c.client_id JOIN district d ON c.district_id = d.district_id WHERE c.gender = 'F'), OldestFemale AS (SELECT account_id FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), LowestAvgSalary AS (SELECT account_id FROM FemaleClientAccounts WHERE avg_salary = (SELECT MIN(avg_salary) FROM FemaleClientAccounts)), TargetAccounts AS (SELECT account_id FROM OldestFemale INTERSECT SELECT account_id FROM LowestAvgSalary), SalaryGap AS (SELECT MAX(avg_salary) - MIN(avg_salary) AS salary_gap FROM FemaleClientAccounts) SELECT t.account_id, s.salary_gap FROM TargetAccounts t CROSS JOIN SalaryGap s"
}

{
    "sql": "WITH FemaleClients AS (SELECT c.client_id, c.birth_date, d.account_id, a.district_id FROM client c JOIN disp d ON c.client_id = d.client_id JOIN account a ON d.account_id = a.account_id WHERE c.gender = 'F'), OldestFemaleClients AS (SELECT account_id FROM FemaleClients WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClients)), DistrictAvgSalary AS (SELECT district_id, A11 AS avg_salary FROM district), AccountAvgSalary AS (SELECT fc.account_id, das.avg_salary FROM FemaleClients fc JOIN DistrictAvgSalary das ON fc.district_id = das.district_id), LowestAvgSalaryAccount AS (SELECT aas.account_id, aas.avg_salary FROM AccountAvgSalary aas JOIN OldestFemaleClients ofc ON aas.account_id = ofc.account_id WHERE aas.avg_salary = (SELECT MIN(avg_salary) FROM AccountAvgSalary aas2 JOIN OldestFemaleClients ofc2 ON aas2.account_id = ofc2.account_id)) SELECT las.account_id, (MAX(d.A11) - MIN(d.A11)) AS salary_gap FROM LowestAvgSalaryAccount las, district d WHERE d.district_id IN (SELECT district_id FROM FemaleClients WHERE account_id = las.account_id)"
}

{
    "sql": "WITH FemaleClientAccounts AS (SELECT DISTINCT a.account_id, c.birth_date FROM account a JOIN disp d ON a.account_id = d.account_id JOIN client c ON d.client_id = c.client_id WHERE c.gender = 'F'), OldestFemaleAccounts AS (SELECT account_id FROM FemaleClientAccounts WHERE birth_date = (SELECT MIN(birth_date) FROM FemaleClientAccounts)), DistrictAvgSalary AS (SELECT district_id, A11 AS avg_salary FROM district), AccountAvgSalary AS (SELECT a.account_id, d.avg_salary FROM account a JOIN DistrictAvgSalary d ON a.district_id = d.district_id), OldestFemaleSalaries AS (SELECT o.account_id, a.avg_salary FROM OldestFemaleAccounts o JOIN AccountAvgSalary a ON o.account_id = a.account_id), MinMaxSalaries AS (SELECT MIN(avg_salary) AS min_salary, MAX(avg_salary) AS max_salary FROM OldestFemaleSalaries) SELECT o.account_id, (m.max_salary - m.min_salary) AS salary_gap FROM OldestFemaleSalaries o, MinMaxSalaries m WHERE o.avg_salary = m.min_salary"
}

